def compute(vars):
    losses = {
        "2019": vars["v1"],
        "2018": vars["v2"],
        "2017": vars["v3"],
    }
    threshold = -10000
    matching_years = [year for year, loss in losses.items() if loss < threshold]
    result = " and ".join(matching_years) if matching_years else None

    return {
        "value": result,
        "trace": {
            "losses": losses,
            "threshold": threshold,
            "matching_years": matching_years,
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
